    kind in ('announcement', 'maintenance', 'holiday', 'feature_release', 'popup')
  ),
  audience text not null default 'everyone' check (
    audience in ('everyone', 'florists', 'wholesalers', 'selected')
  ),
  audience_user_ids uuid[] default '{}',
