-- ---------------------------------------------------------------------------
-- Replace RLS policies — drop every R1/v1 policy name before recreate
-- ---------------------------------------------------------------------------

-- Profiles
drop policy if exists "community profiles select authenticated" on public.florist_community_profiles;
drop policy if exists "community profiles select active florist" on public.florist_community_profiles;
create policy "community profiles select active florist"
  on public.florist_community_profiles
  for select
  to authenticated
  using (public.is_active_florist() or public.is_platform_admin_user());

drop policy if exists "community profiles insert own" on public.florist_community_profiles;
create policy "community profiles insert own"
  on public.florist_community_profiles
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and public.is_active_member_of(shop_id)
  );

drop policy if exists "community profiles update own" on public.florist_community_profiles;
create policy "community profiles update own"
  on public.florist_community_profiles
  for update
  to authenticated
  using (user_id = auth.uid() and public.is_active_florist())
  with check (
    user_id = auth.uid()
    and public.is_active_member_of(shop_id)
  );

-- Posts
drop policy if exists "community posts select" on public.florist_community_posts;
create policy "community posts select"
  on public.florist_community_posts
  for select
  to authenticated
  using (
    (
      public.is_active_florist()
      and status = 'active'
    )
    or (
      -- Narrow exceptions: author or authorized moderators may read moderated rows.
      public.is_active_florist()
      and author_user_id = auth.uid()
    )
    or public.is_platform_admin_user()
    or (
      public.is_active_florist()
      and public.is_shop_manager_of(shop_id)
    )
  );

drop policy if exists "community posts insert" on public.florist_community_posts;
create policy "community posts insert"
  on public.florist_community_posts
  for insert
  to authenticated
  with check (
    author_user_id = auth.uid()
    and public.is_active_member_of(shop_id)
    and status = 'active'
    and like_count = 0
    and comment_count = 0
    and (
      image_path is null
      or image_path ~ ('^' || shop_id::text || '/' || author_user_id::text || '/.+')
    )
  );

drop policy if exists "community posts update" on public.florist_community_posts;
drop policy if exists "community posts update author content" on public.florist_community_posts;
drop policy if exists "community posts update moderator" on public.florist_community_posts;
-- Authors may edit supported content fields on their own ACTIVE content only.
-- No moderator UPDATE policy — moderation is status-only via RPC.
create policy "community posts update author content"
  on public.florist_community_posts
  for update
  to authenticated
  using (
    author_user_id = auth.uid()
    and public.is_active_florist()
    and status = 'active'
  )
  with check (
    author_user_id = auth.uid()
    and public.is_active_member_of(shop_id)
    and status = 'active'
    and (
      image_path is null
      or image_path ~ ('^' || shop_id::text || '/' || author_user_id::text || '/.+')
    )
  );

drop policy if exists "community posts delete" on public.florist_community_posts;
-- Authors may hard-delete own rows. Moderators cannot hard-delete.
create policy "community posts delete"
  on public.florist_community_posts
  for delete
  to authenticated
  using (
    author_user_id = auth.uid()
    and public.is_active_florist()
  );

-- Comments
drop policy if exists "community comments select" on public.florist_community_comments;
create policy "community comments select"
  on public.florist_community_comments
  for select
  to authenticated
  using (
    public.florist_community_post_visible(post_id)
    and (
      (
        public.is_active_florist()
        and status = 'active'
        and exists (
          select 1 from public.florist_community_posts p
          where p.id = post_id and p.status = 'active'
        )
      )
      or (
        public.is_active_florist()
        and author_user_id = auth.uid()
      )
      or public.is_platform_admin_user()
      or (
        public.is_active_florist()
        and public.is_shop_manager_of(shop_id)
      )
    )
  );

drop policy if exists "community comments insert" on public.florist_community_comments;
create policy "community comments insert"
  on public.florist_community_comments
  for insert
  to authenticated
  with check (
    author_user_id = auth.uid()
    and public.is_active_member_of(shop_id)
    and status = 'active'
    and exists (
      select 1 from public.florist_community_posts p
      where p.id = post_id and p.status = 'active'
    )
  );

drop policy if exists "community comments update" on public.florist_community_comments;
drop policy if exists "community comments update author content" on public.florist_community_comments;
create policy "community comments update author content"
  on public.florist_community_comments
  for update
  to authenticated
  using (
    author_user_id = auth.uid()
    and public.is_active_florist()
    and status = 'active'
  )
  with check (
    author_user_id = auth.uid()
    and public.is_active_member_of(shop_id)
    and status = 'active'
  );

drop policy if exists "community comments delete" on public.florist_community_comments;
create policy "community comments delete"
  on public.florist_community_comments
  for delete
  to authenticated
  using (
    author_user_id = auth.uid()
    and public.is_active_florist()
  );

-- Likes
drop policy if exists "community likes select" on public.florist_community_likes;
create policy "community likes select"
  on public.florist_community_likes
  for select
  to authenticated
  using (
    public.is_active_florist()
    and (
      exists (
        select 1 from public.florist_community_posts p
        where p.id = post_id and p.status = 'active'
      )
      or public.is_platform_admin_user()
      or exists (
        select 1 from public.florist_community_posts p
        where p.id = post_id
          and (
            p.author_user_id = auth.uid()
            or public.is_shop_manager_of(p.shop_id)
          )
      )
    )
  );

drop policy if exists "community likes insert" on public.florist_community_likes;
create policy "community likes insert"
  on public.florist_community_likes
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and public.is_active_member_of(shop_id)
    and exists (
      select 1 from public.florist_community_posts p
      where p.id = post_id and p.status = 'active'
    )
  );

drop policy if exists "community likes delete" on public.florist_community_likes;
create policy "community likes delete"
  on public.florist_community_likes
  for delete
  to authenticated
  using (user_id = auth.uid() and public.is_active_florist());

-- Reports: insert + select only; no direct UPDATE/DELETE policies
drop policy if exists "community reports insert" on public.florist_community_reports;
create policy "community reports insert"
  on public.florist_community_reports
  for insert
  to authenticated
  with check (
    reporter_user_id = auth.uid()
    and public.is_active_member_of(reporter_shop_id)
    and status = 'open'
    and exists (
      select 1 from public.florist_community_posts p
      where p.id = post_id and p.status = 'active'
    )
  );

drop policy if exists "community reports select own or admin" on public.florist_community_reports;
create policy "community reports select own or admin"
  on public.florist_community_reports
  for select
  to authenticated
  using (
    (
      public.is_active_florist()
      and reporter_user_id = auth.uid()
    )
    or public.is_platform_admin_user()
  );

drop policy if exists "community reports update admin" on public.florist_community_reports;
-- Intentionally no UPDATE/DELETE policies for reports (status via RPC only).

-- ---------------------------------------------------------------------------
-- Private storage bucket + active-post image readability
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'florist-community',
  'florist-community',
  false,
  2097152,
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "community images select" on storage.objects;
drop policy if exists "community images select active florist" on storage.objects;
create policy "community images select active florist"
  on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'florist-community'
    and public.florist_community_image_readable(name)
  );

drop policy if exists "community images insert member" on storage.objects;
create policy "community images insert member"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'florist-community'
    and (storage.foldername(name))[1] ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    and (storage.foldername(name))[2] = auth.uid()::text
    and public.is_active_member_of((storage.foldername(name))[1]::uuid)
  );

drop policy if exists "community images update" on storage.objects;

drop policy if exists "community images delete own" on storage.objects;
-- Only the active image owner may directly delete their object.
-- Managers/platform admins moderate via status-only RPCs; service_role cleanup remains.
create policy "community images delete own"
  on storage.objects
  for delete
  to authenticated
  using (
    bucket_id = 'florist-community'
    and (storage.foldername(name))[2] = auth.uid()::text
    and public.is_active_florist()
  );

drop policy if exists "community images service role" on storage.objects;
create policy "community images service role"
  on storage.objects
  for all
  to service_role
  using (bucket_id = 'florist-community')
  with check (bucket_id = 'florist-community');

-- ---------------------------------------------------------------------------
-- Explicit minimum table privileges (production-shaped; no broad anon access)
-- ---------------------------------------------------------------------------

revoke all on table public.florist_community_profiles from anon;
revoke all on table public.florist_community_posts from anon;
revoke all on table public.florist_community_comments from anon;
revoke all on table public.florist_community_likes from anon;
revoke all on table public.florist_community_reports from anon;

grant select, insert, update on table public.florist_community_profiles to authenticated;
grant select, insert, update, delete on table public.florist_community_posts to authenticated;
grant select, insert, update, delete on table public.florist_community_comments to authenticated;
grant select, insert, delete on table public.florist_community_likes to authenticated;
grant select, insert on table public.florist_community_reports to authenticated;

grant all on table public.florist_community_profiles to service_role;
grant all on table public.florist_community_posts to service_role;
grant all on table public.florist_community_comments to service_role;
grant all on table public.florist_community_likes to service_role;
grant all on table public.florist_community_reports to service_role;

notify pgrst, 'reload schema';
-- END SOURCE: supabase/legacy_migrations/20260731_florist_community_beta_v1_r1_security.sql

-- BEGIN SOURCE: supabase/legacy_migrations/20260801_p0_01_floral_library_schema_lock_v1.sql
-- P0-01 / R1 — Floral Library schema exposure lock (least-privilege role alignment).
-- Forward-only. Does not rewrite prior migration history beyond this lock file.
-- Does not depend on Community migrations or Community helper functions.
--
-- Targets:
--   public.bloom_floral_library_master
--   public.bloom_library_import_batches
--
-- Closed beta: only an active super_admin receives elevated master visibility.
-- Authenticated JWT clients cannot mutate master rows; service_role only.

-- Retire the obsolete P0-01 generic helper so it cannot remain callable.
drop function if exists public.is_active_platform_admin();

-- Capability-specific helper: unapproved master visibility for active super_admin only.
create or replace function public.can_read_unapproved_floral_library_master()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select
    auth.uid() is not null
    and exists (
      select 1
      from public.platform_admins as pa
      where pa.user_id = auth.uid()
        and pa.active = true
        and lower(pa.role) = 'super_admin'
    );
$$;

revoke all on function public.can_read_unapproved_floral_library_master() from public;
revoke all on function public.can_read_unapproved_floral_library_master() from anon;
grant execute on function public.can_read_unapproved_floral_library_master() to authenticated;
grant execute on function public.can_read_unapproved_floral_library_master() to service_role;

-- ---------------------------------------------------------------------------
-- bloom_floral_library_master
-- ---------------------------------------------------------------------------
alter table public.bloom_floral_library_master enable row level security;

drop policy if exists "floral library master read" on public.bloom_floral_library_master;
drop policy if exists "floral library master select approved" on public.bloom_floral_library_master;
drop policy if exists "floral library master admin insert" on public.bloom_floral_library_master;
drop policy if exists "floral library master admin update" on public.bloom_floral_library_master;
drop policy if exists "floral library master admin delete" on public.bloom_floral_library_master;

-- Authenticated SELECT only:
--   - approved_starter / approved for ordinary users
--   - plus unapproved rows for active super_admin
create policy "floral library master select approved"
  on public.bloom_floral_library_master
  for select
  to authenticated
  using (
    review_status in ('approved_starter', 'approved')
    or public.can_read_unapproved_floral_library_master()
  );

-- No authenticated INSERT/UPDATE/DELETE policies.
-- Master mutations require a separately reviewed service-role workflow.

revoke all on table public.bloom_floral_library_master from public;
revoke all on table public.bloom_floral_library_master from anon;
revoke all on table public.bloom_floral_library_master from authenticated;
grant select on table public.bloom_floral_library_master to authenticated;
grant select, insert, update, delete on table public.bloom_floral_library_master to service_role;

-- ---------------------------------------------------------------------------
-- bloom_library_import_batches
-- Service-role / platform import processing only.
-- No PUBLIC/anon/authenticated access. Zero JWT policies.
-- ---------------------------------------------------------------------------
alter table public.bloom_library_import_batches enable row level security;

drop policy if exists "library import batches open" on public.bloom_library_import_batches;
drop policy if exists "library import batches all" on public.bloom_library_import_batches;
drop policy if exists "library import batches select" on public.bloom_library_import_batches;
drop policy if exists "library import batches write" on public.bloom_library_import_batches;

revoke all on table public.bloom_library_import_batches from public;
revoke all on table public.bloom_library_import_batches from anon;
revoke all on table public.bloom_library_import_batches from authenticated;
grant select, insert, update, delete on table public.bloom_library_import_batches to service_role;
-- END SOURCE: supabase/legacy_migrations/20260801_p0_01_floral_library_schema_lock_v1.sql

-- BEGIN SOURCE: supabase/baseline_fragments/identity_onboarding.sql
-- Canonical identity provisioning and florist onboarding contract.
--
-- This replaces the obsolete root schema trigger, which populated owner_id but
-- not the foundation's required owner_user_id column. It also materializes the
-- authenticated onboarding RPC that exists live but was absent from source.

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  new_shop_id uuid;
begin
  insert into public.shops (owner_user_id, owner_id, name)
  values (
    new.id,
    new.id,
    coalesce(new.raw_user_meta_data->>'shop_name', 'My Flower Shop')
  )
  returning id into new_shop_id;

  insert into public.profiles (id, full_name, default_shop_id)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', ''), new_shop_id);

  insert into public.shop_members (shop_id, user_id, role, status)
  values (new_shop_id, new.id, 'owner', 'active');

  return new;
end;
$$;

revoke all privileges on function public.handle_new_user()
  from public, anon, authenticated, service_role;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

create or replace function public.complete_florist_onboarding(
  p_shop_name text,
  p_full_name text default null,
  p_phone text default null,
  p_email text default null,
  p_website text default null,
  p_address_line_1 text default null,
  p_address_line_2 text default null,
  p_city text default null,
  p_state text default null,
  p_postal_code text default null,
  p_timezone text default 'America/New_York',
  p_tax_rate numeric default 0,
  p_delivery_fee numeric default 0,
  p_receipt_header text default null,
  p_shop_tone text default 'warm, capable, florist-friendly',
  p_delivery_notes text default null,
  p_marketing_notes text default null
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_user_id uuid := auth.uid();
  v_shop_id uuid;
  v_shop_slug text;
begin
  if v_user_id is null then
    raise exception 'You must be signed in.';
  end if;

  if nullif(btrim(p_shop_name), '') is null then
    raise exception 'Shop name is required.';
  end if;

  if coalesce(p_tax_rate, 0) < 0 or coalesce(p_tax_rate, 0) > 100 then
    raise exception 'Tax rate must be between 0 and 100.';
  end if;

  if coalesce(p_delivery_fee, 0) < 0 then
    raise exception 'Delivery fee cannot be negative.';
  end if;

  select profile.default_shop_id
  into v_shop_id
  from public.profiles profile
  where profile.id = v_user_id;

  if v_shop_id is null then
    v_shop_slug := trim(both '-' from regexp_replace(lower(p_shop_name), '[^a-z0-9]+', '-', 'g'))
      || '-' || left(v_user_id::text, 6);

    insert into public.shops (
      name, slug, owner_user_id, owner_id, onboarding_complete, phone, email,
      website, address_line_1, address_line_2, city, state, postal_code,
      timezone, tax_rate, default_delivery_fee, receipt_header
    )
    values (
      btrim(p_shop_name), v_shop_slug, v_user_id, v_user_id, true, p_phone, p_email,
      p_website, p_address_line_1, p_address_line_2, p_city, p_state,
      p_postal_code, coalesce(nullif(p_timezone, ''), 'America/New_York'),
      coalesce(p_tax_rate, 0), coalesce(p_delivery_fee, 0),
      coalesce(nullif(p_receipt_header, ''), btrim(p_shop_name))
    )
    returning id into v_shop_id;

    insert into public.shop_members (shop_id, user_id, role, status)
    values (v_shop_id, v_user_id, 'owner', 'active')
    on conflict do nothing;

    insert into public.profiles (id, full_name, default_shop_id)
    values (v_user_id, p_full_name, v_shop_id)
    on conflict (id) do update
      set full_name = coalesce(excluded.full_name, public.profiles.full_name),
          default_shop_id = excluded.default_shop_id,
          updated_at = now();

    insert into public.shop_subscriptions (shop_id, plan_code, status, trial_ends_at)
    values (v_shop_id, 'trial', 'trialing', now() + interval '14 days')
    on conflict do nothing;

    insert into public.ai_shop_profiles (
      shop_id, lily_enabled, rose_enabled, shop_tone,
      delivery_notes, marketing_notes
    )
    values (
      v_shop_id, true, true,
      coalesce(p_shop_tone, 'warm, capable, florist-friendly'),
      p_delivery_notes, p_marketing_notes
    )
    on conflict do nothing;

    insert into public.shop_settings (
      shop_id, tax_rate, default_delivery_fee, timezone, currency, receipt_header
    )
    values (
      v_shop_id, coalesce(p_tax_rate, 0), coalesce(p_delivery_fee, 0),
      coalesce(nullif(p_timezone, ''), 'America/New_York'), 'USD',
      coalesce(nullif(p_receipt_header, ''), btrim(p_shop_name))
    )
    on conflict do nothing;

    for day_index in 0..6 loop
      insert into public.shop_hours (shop_id, weekday, is_closed, opens_at, closes_at)
      select v_shop_id, day_index, day_index = 0,
             case when day_index = 0 then null else time '09:00' end,
             case when day_index = 0 then null else time '17:00' end
      where not exists (
        select 1
        from public.shop_hours hours
        where hours.shop_id = v_shop_id
          and hours.weekday = day_index
      );
    end loop;
  else
    if not public.user_is_shop_owner(v_shop_id) then
      raise exception 'Only the shop owner can complete setup.';
    end if;

    update public.shops
    set name = btrim(p_shop_name),
        onboarding_complete = true,
        phone = p_phone,
        email = p_email,
        website = p_website,
        address_line_1 = p_address_line_1,
        address_line_2 = p_address_line_2,
        city = p_city,
        state = p_state,
        postal_code = p_postal_code,
        timezone = coalesce(nullif(p_timezone, ''), timezone),
        tax_rate = coalesce(p_tax_rate, tax_rate),
        default_delivery_fee = coalesce(p_delivery_fee, default_delivery_fee),
        receipt_header = coalesce(nullif(p_receipt_header, ''), receipt_header),
        updated_at = now()
    where id = v_shop_id;
  end if;

  return v_shop_id;
end;
$$;

revoke all privileges on function public.complete_florist_onboarding(
  text, text, text, text, text, text, text, text, text, text, text,
  numeric, numeric, text, text, text, text
) from public, anon, authenticated, service_role;
grant execute on function public.complete_florist_onboarding(
  text, text, text, text, text, text, text, text, text, text, text,
  numeric, numeric, text, text, text, text
) to authenticated, service_role;
-- END SOURCE: supabase/baseline_fragments/identity_onboarding.sql
